import React from 'react';
import { theme, Box } from '..';

export const getSemanticColors = (semanticTokens) =>
  Object.keys(semanticTokens).reduce((acc, curr) => {
    acc[curr] = theme.colors[semanticTokens[curr]];
    return acc;
  }, {});

interface DesignTokenComponentProps {
  token: string;
  options: string[];
}

export const DesignTokenOptions = ({ token, options = [] }: DesignTokenComponentProps) => (
  <Box display="flex" gap="2" alignItems="center">
    {options.map((option, index) => (
      <Box
        borderColor="border"
        borderStyle="solid"
        borderWidth="sm"
        key={index}
        padding="8"
        outlineColor="grey_1200"
        outlineStyle="solid"
        outlineWidth={token.startsWith('outline') ? 'sm' : undefined}
        {...{ [token]: option }}
      >
        <Box as="p">{option}</Box>
      </Box>
    ))}
  </Box>
);

export const TypographyDesignTokenOptions = ({ token, options = [] }: DesignTokenComponentProps) => (
  <Box display="flex" gap="2">
    {options.map((option) => (
      <Box as="p" color="grey_1200" fontStyle="normal" fontSize="b_md" key={option} {...{ [token]: option }}>
        {option}
      </Box>
    ))}
  </Box>
);
